// Concept atlas and reversible random-route demonstration. By Astra, Codex GPT-6.
(()=>{'use strict';const data=JSON.parse(document.getElementById('world-data').textContent),scenes=data.scenes,$=id=>document.getElementById(id);let route=[];
  function picture(el,n){const index=n-1;el.style.backgroundImage='url(liminal-doors-assets/liminal-doors-plate-'+String(n===37?7:Math.floor(index/6)+1).padStart(2,'0')+'-20261015.png)';el.style.backgroundSize=n===37?'cover':'200% 300%';el.style.backgroundPosition=n===37?'center':(index%2?100:0)+'% '+(Math.floor(index%6/2)*50)+'%';}
  function show(n,push=true){const s=scenes.find(s=>s.number===n);if(!s)return;if(push)route.push(n);$('detail-number').textContent='Floor '+String(n).padStart(2,'0')+' / '+s.palette;$('detail-title').textContent=s.animal+' · '+s.environment;$('detail-atmosphere').textContent=s.atmosphere;picture($('detail-image'),n);$('detail-image').setAttribute('aria-label',s.environment+' concept art');$('detail-facts').replaceChildren();for(const [label,value] of [['The door',s.door],['A little strangeness',s.feature],['Hidden animal proposal',s.hide]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;$('detail-facts').append(dt,dd);}$('route').textContent='Your route: '+route.map(n=>scenes.find(s=>s.number===n).animal).join(' → ');$('back-door').disabled=route.length<2;$('manage-floor').href='the-threshold-20261016.html#floor-'+n;if(!$('detail').open)$('detail').showModal();}
  function next(){const excluded=new Set(route.slice(-3));const choices=scenes.filter(s=>!excluded.has(s.number));show(choices[Math.floor(Math.random()*choices.length)].number);}
  function render(){const q=$('search').value.toLowerCase(),filter=$('filter').value;const list=scenes.filter(s=>(s.animal+' '+s.environment+' '+s.palette+' '+s.feature).toLowerCase().includes(q)&&(filter==='all'||s.tags.includes(filter)));$('floors').replaceChildren();for(const s of list){const a=document.createElement('article');a.className='floor';const img=document.createElement('div');img.className='floor-image';img.setAttribute('role','img');img.setAttribute('aria-label',s.environment+' concept art');picture(img,s.number);const box=document.createElement('div');box.className='floor-copy';const no=document.createElement('span');no.className='eyebrow';no.textContent='Floor '+String(s.number).padStart(2,'0');const h=document.createElement('h3');h.textContent=s.animal;const p=document.createElement('p');p.textContent=s.environment;const button=document.createElement('button');button.textContent='Enter '+s.animal+' ↗';button.onclick=()=>{route=[];show(s.number);};box.append(no,h,p,button);a.append(img,box);$('floors').append(a);}$('results').textContent=list.length+' / '+scenes.length+' places';}
  $('search').oninput=render;$('filter').onchange=render;$('close-detail').onclick=()=>$('detail').close();$('next-door').onclick=next;$('back-door').onclick=()=>{if(route.length>1){route.pop();show(route.at(-1),false);}};$('wander').onclick=()=>{route=[];show(1);};render();const n=Number(location.hash.replace('#floor-',''));if(n)show(n);
})();
